package com.onlinelearning.controller;
import com.onlinelearning.model.*; import com.onlinelearning.repository.UserRepository; import com.onlinelearning.security.JwtService; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/auth") public class AuthController {private final UserRepository users;private final PasswordEncoder enc;private final JwtService jwt;public AuthController(UserRepository u,PasswordEncoder e,JwtService j){users=u;enc=e;jwt=j;} public record Register(String username,String email,String password,Role role){} public record Login(String username,String password){} public record Response(String token,Long userId,String username,String email,Role role){}
@PostMapping("/register") public Response register(@RequestBody Register r){if(users.existsByUsername(r.username()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Username already exists");if(users.existsByEmail(r.email()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Email already exists");Role role=r.role()==Role.INSTRUCTOR?Role.INSTRUCTOR:Role.STUDENT;User u=users.save(new User(r.username(),r.email(),enc.encode(r.password()),role));return out(u);} @PostMapping("/login") public Response login(@RequestBody Login r){User u=users.findByUsername(r.username()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid username or password"));if(!enc.matches(r.password(),u.getPassword()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid username or password");return out(u);} private Response out(User u){return new Response(jwt.generate(u.getUsername(),u.getRole().name()),u.getId(),u.getUsername(),u.getEmail(),u.getRole());}}